    53→	cmd := &cobra.Command{
    54→		Use:   "enable",
    55→		Short: "Enable Entire",
    56→		Long: `Enable Entire with session tracking for your AI agent workflows.
    57→
    58→Uses the manual-commit strategy by default. To use a different strategy:
    59→
    60→  entire enable --strategy auto-commit
    61→
    62→Strategies: manual-commit (default), auto-commit`,
    63→		RunE: func(cmd *cobra.Command, _ []string) error {
    64→			// Check if we're in a git repository first - this is a prerequisite error,
    65→			// not a usage error, so we silence Cobra's output and use SilentError
    66→			// to prevent duplicate error output in main.go
    67→			if _, err := paths.RepoRoot(); err != nil {
    68→				cmd.SilenceUsage = true
    69→				cmd.SilenceErrors = true
    70→				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire enable' from within a git repository.")
    71→				return NewSilentError(errors.New("not a git repository"))
    72→			}
    73→
    74→			if err := validateSetupFlags(useLocalSettings, useProjectSettings); err != nil {
    75→				return err
    76→			}
    77→			// Non-interactive mode if --agent flag is provided
    78→			if agentName != "" {
    79→				return setupAgentHooksNonInteractive(agent.AgentName(agentName), strategyFlag, localDev, forceHooks, skipPushSessions, telemetry, disableMultisessionWarning)
    80→			}
    81→			// If strategy is specified via flag, skip interactive selection
    82→			if strategyFlag != "" {
    83→				return runEnableWithStrategy(cmd.OutOrStdout(), strategyFlag, localDev, ignoreUntracked, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, telemetry, disableMultisessionWarning)
    84→			}
    85→			return runEnableInteractive(cmd.OutOrStdout(), localDev, ignoreUntracked, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, telemetry, disableMultisessionWarning)
    86→		},
    87→	}
